**suggestion (non-blocking):** I think this function can be refactored as follows to avoid nested `if` statements.

```js
const parseEnvironmentVariables = (
  envString: string,
): Record<string, string> => {
  const env: Record<string, string> = {};
  if (!envString.trim()) {
    return env;
  }

  for (const line of envString.split("\n")) {
    const trimmedLine = line.trim();
    if (!trimmedLine) {
      continue;
    }

    const equalIndex = trimmedLine.indexOf("=");
    if (equalIndex === -1) {
      continue;
    }

    const key = trimmedLine.substring(0, equalIndex).trim();
    if (!key) {
      continue;
    }

    const value = trimmedLine.substring(equalIndex + 1).trim();
    env[key] = value;
  }
  return env;
};
```

